    },
    {
      "type": "invest_infrastructure",
      "target": null,
      "amount": 1.0,
      "sub": "",
      "order": "Boost infrastructure investment by 1% of GDP to support economic resilience."
    },
    {
      "type": "military_mobilize",
      "target": null,
      "amount": 0.2,
      "sub": "",
      "order": "Mobilize 20% of reserves to strengthen border readiness."
    }
  ],
  "cables": [
    {
      "to": "GEO",
      "private": true,
      "text": "We reaffirm our commitment to regional stability and desire good neighbourly relations."
    }
  ],
  "public_statement": "The Government of Armenia remains committed to safeguarding the peace, security, and prosperity of all our citizens while strengthening our defensive capabilities against potential regional threats.",
